exercise.referenceSolution:
#include <ctype.h>
#include <stdio.h>

size_t count_char(const char *s, char c) {
    size_t count = 0;
    for (; *s != '\0'; s++) {
        if (*s == c) {
            count++;
        }
    }
    return count;
}

size_t count_words(const char *s) {
    size_t count = 0;
    int inside = 0;
    for (; *s != '\0'; s++) {
        if (isspace((unsigned char)*s)) {
            inside = 0;
        } else if (!inside) {
            inside = 1;
            count++;
        }
    }
    return count;
}

int main(void) {
    char line[256];
    char symbol[8];
    if (fgets(line, sizeof line, stdin) == NULL || fgets(symbol, sizeof symbol, stdin) == NULL) {
        return 1;
    }
    printf("chars=%zu words=%zu\n", count_char(line, symbol[0]), count_words(line));
    return 0;
}

