#include <stdio.h>

const char *skip_spaces(const char *s) {
    while (*s == ' ') {
        s++;
    }
    return s;
}

int main(void) {
    const char *text = "   hello";
    const char *start = skip_spaces(text);
    printf("%td %s\n", start - text, start);
    return 0;
}

#include <stdio.h>

struct Box {
    int w, h;
};

int area(const struct Box *b) {
    return b->w * b->h;
}

void grow(struct Box *b) {
    b->w++;
    b->h++;
}

int main(void) {
    struct Box box = {2, 3};
    grow(&box);
    printf("%d\n", area(&box));
    return 0;
}
